import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int q = Integer.parseInt(st.nextToken());
        // Per type: a min-heap of released ids and the next never-used id.
        HashMap<String, PriorityQueue<Long>> freed = new HashMap<>();
        HashMap<String, Long> nxt = new HashMap<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String op = st.nextToken(), type = st.nextToken();
            PriorityQueue<Long> heap = freed.computeIfAbsent(type, k -> new PriorityQueue<>());
            if (op.equals("allocate")) {
                long x;
                if (!heap.isEmpty()) x = heap.poll();
                else {
                    x = nxt.getOrDefault(type, 1L);
                    nxt.put(type, x + 1);
                }
                sb.append(x).append('\n');
            } else {
                heap.add(Long.parseLong(st.nextToken()));
            }
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"container/heap"
	"os"
	"strconv"
)

type minHeap []int64

func (h minHeap) Len() int           { return len(h) }
func (h minHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *minHeap) Pop() any {
	old := *h
	v := old[len(old)-1]
	*h = old[:len(old)-1]
	return v
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() string {
		sc.Scan()
		return sc.Text()
	}
	q, _ := strconv.Atoi(next())
	// Per type: a min-heap of released ids and the next never-used id.
	freed := map[string]*minHeap{}
	nxt := map[string]int64{}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < q; i++ {
		op, t := next(), next()
		h, ok := freed[t]
		if !ok {
			h = &minHeap{}
			freed[t] = h
			nxt[t] = 1
		}
		if op == "allocate" {
			var x int64
			if h.Len() > 0 {
				x = heap.Pop(h).(int64)
			} else {
				x = nxt[t]
				nxt[t]++
			}
			w.WriteString(strconv.FormatInt(x, 10) + "\n")
		} else {
			x, _ := strconv.ParseInt(next(), 10, 64)
			heap.Push(h, x)
		}
	}
}
